-- 1. Eksik Olan CampaignRules (Saat bazlı, gün bazlı ve ürün bazlı kurallar için)
CREATE TABLE "CampaignRules" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "campaign_id" int REFERENCES "Campaigns"("id") ON DELETE CASCADE,
  "rule_type" varchar(50), -- Örn: 'TIME_RANGE', 'PRODUCT_COMBO', 'DISCOUNT_PERCENT', 'DISCOUNT_FIXED'
  "rule_value" varchar(255), -- Örn: '14:00-17:00' veya '15' (yüzde)
  "target_product_id" int REFERENCES "Products"("id")
);

-- 2. Eksik Olan Notifications (Bildirimler tablosu)
CREATE TABLE "Notifications" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "user_id" int REFERENCES "Users"("id") ON DELETE CASCADE,
  "title" varchar(150),
  "message" text,
  "is_read" boolean DEFAULT false,
  "created_at" timestamp DEFAULT (now())
);

-- 3. Hocanın Kriteri: Aynı siparişe çift puan yazılmasını ve kupon tekrarını engelleyen kilitler
CREATE UNIQUE INDEX "idx_unique_loyalty_earn" ON "LoyaltyTransactions" ("order_id", "transaction_type") WHERE "transaction_type" = 'EARN';
CREATE UNIQUE INDEX "idx_unique_coupon_user" ON "CouponRedemptions" ("coupon_id", "user_id");

